solutionCode:
pub struct Ponto {
    pub x: i32,
    pub y: i32,
}

pub fn ponto_de(x: i32, y: i32) -> Ponto {
    Ponto { x: x, y: y }
}

pub fn ponto_espelhado(x: i32, y: i32) -> Ponto {
    Ponto { x: -x, y: -y }
}

testsCode:
use desafio::ponto_de;
use desafio::ponto_espelhado;

#[test]
fn testa_o_x_do_ponto_montado_dois_por_tres() {
    assert_eq!(ponto_de(2, 3).x, 2);
}

#[test]
fn testa_o_y_do_ponto_montado_cinco_por_sete() {
    assert_eq!(ponto_de(5, 7).y, 7);
}

#[test]
fn testa_o_x_do_ponto_espelhado_negativo_quatro_por_cinco() {
    assert_eq!(ponto_espelhado(-4, 5).x, 4);
}

#[test]
fn testa_o_y_do_ponto_espelhado_dois_por_tres() {
    assert_eq!(ponto_espelhado(2, 3).y, -3);
}
